<script setup>import {Head,Link} from '@inertiajs/vue3';import AppLayout from '../../../Layouts/AppLayout.vue';defineProps({managedUser:Object,studentReport:Object,teacherSummary:Object,sessions:Array,summaries:Object});const labels={ADMIN:'مدیر',TEACHER:'مدرس',STUDENT:'هنرجو'};</script>
<template><AppLayout><Head :title="managedUser.name"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-4"><div class="flex items-center gap-4"><img v-if="managedUser.avatar_url" :src="managedUser.avatar_url" class="h-20 w-20 rounded-full object-cover"><div v-else class="grid h-20 w-20 place-items-center rounded-full bg-teal-50 text-xl font-bold">{{managedUser.first_name?.[0]}}{{managedUser.last_name?.[0]}}</div><div><h1 class="text-2xl font-bold">{{managedUser.name}}</h1><p>{{labels[managedUser.role]}} · <span :class="managedUser.is_active?'text-emerald-700':'text-red-700'">{{managedUser.is_active?'فعال':'غیرفعال'}}</span></p></div></div><Link :href="`/admin/users/${managedUser.id}/edit`" class="rounded-xl border px-4 py-2">ویرایش حساب</Link></div><div class="mt-5 grid gap-2 text-sm sm:grid-cols-2"><p>موبایل: <span dir="ltr">{{managedUser.mobile}}</span></p><p>ایمیل: {{managedUser.email||'—'}}</p><p>ایجاد حساب: {{new Date(managedUser.created_at).toLocaleString('fa-IR')}}</p><p>نشست فعال: {{sessions.length}}</p></div><div v-if="managedUser.bio||managedUser.teacher_specialty" class="mt-4 rounded-xl bg-slate-50 p-4"><strong>{{managedUser.teacher_specialty}}</strong><p class="mt-2 whitespace-pre-line">{{managedUser.bio}}</p><p class="mt-2 whitespace-pre-line">{{managedUser.teacher_experience_text}}</p></div></section><section v-if="studentReport" class="rounded-2xl border bg-white p-5"><h2 class="font-bold">دوره‌ها و پیشرفت هنرجو</h2><div class="mt-4 grid gap-3 sm:grid-cols-2"><article v-for="c in studentReport.courses" :key="c.id" class="rounded-xl border p-3"><div class="flex justify-between"><Link :href="`/admin/reports/students/${managedUser.id}?course=${c.id}`" class="font-bold text-teal-700">{{c.title}}</Link><strong>{{c.percent}}٪</strong></div><p class="text-sm">{{c.completed_lessons}} از {{c.total_lessons}} درس · {{c.enrollment_status}}</p></article></div></section><section v-if=